    function run(address recipient, uint256 value, bool callerIsOwner) public payable {
        require(address(this).balance >= value);
        address ownerBefore = c.Owner();
        uint256 cBefore = address(c).balance;

        if (callerIsOwner && msg.sender != ownerBefore) {
            // impersonate owner is impossible; force non-owner branch
        }

        bool reverted;
        if (callerIsOwner) {
            // only valid if msg.sender is owner; otherwise this branch is unreachable safely
            require(msg.sender == ownerBefore);
            try c.multiplicate{value: value}(recipient) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            require(msg.sender != ownerBefore);
            try c.multiplicate{value: value}(recipient) {
                reverted = false;
            } catch {
                reverted = true;
            }
