        bool expectedComplete = ownerCall && !(value >= cBefore && recipientRejectsTransfer(recipient));
        uint256 expectedAfter = value >= cBefore ? cBefore + value : cBefore;

        assert(
            (reverted == expectedRevert) &&
            (!reverted || !ownerCall || value < cBefore ? (reverted || !ownerCall ? true : cAfter == expectedAfter) : true) &&
            (reverted || !ownerCall ? true : cAfter == expectedAfter) &&
            (!reverted && value < cBefore) ? cAfter == cBefore : true
        );
    }

    function recipientRejectsTransfer(address) internal pure returns (bool) {
        return false;
    }

