        c = _c;
    }

    function run(address recipient, uint256 value) public payable {
        require(address(this).balance >= value);

        uint256 cBefore = address(c).balance;

        bool reverted;
        try c.multiplicate{value: value}(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 cAfter = address(c).balance;

        if (value >= cBefore) {
            // Either the transfer to recipient was rejected (call reverts, cAfter == cBefore),
            // or it succeeded (call completes, cAfter == cBefore + value).
            assert(reverted ? cAfter == cBefore : cAfter == cBefore + value);
        } else {
            // No transfer is attempted: the call must complete and cAfter == cBefore.
            assert(!reverted && cAfter == cBefore);
        }
    }

    receive() external payable {}
}

