        try c.multiplicate{value: amount}(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool callerIsTest = msg.sender == address(this);
        bool attemptedTransfer = amount >= preBalance;
        bool completes = !reverted;

        if (!callerIsTest) {
            assert(reverted);
        } else if (attemptedTransfer) {
            if (recipient == address(this)) {
                assert(completes);
            } else {
                // Without a way to observe whether the recipient rejects, the rule is
                // non-reversion is not generally provable; assert the observable balance
                // invariant when the call completes.
                if (completes) {
                    assert(address(c).balance == preBalance + amount);
                } else {
                    assert(true);
                }
            }
        } else {
            assert(completes);
        }
    }
}

